window.CERTS = window.CERTS || {};
window.CERTS["dva-c02"] = {
  code: "DVA-C02",
  title: "AWS Certified Developer - Associate",
  level: "Associate",
  blurb: "Building, securing, deploying, and debugging applications on AWS.",
  exam: { count: 65, minutes: 130, pass: 72 },
  domains: [
    { name: "Development with AWS Services", weight: 32 },
    { name: "Security", weight: 26 },
    { name: "Deployment", weight: 24 },
    { name: "Troubleshooting and Optimization", weight: 18 }
  ],
  // First option in each "o" array is the correct answer (the app shuffles). d = domain index.
  // ma = indices of all correct options for choose-two questions.
  questions: [
// ---------- Domain 0: Development with AWS Services ----------
{d:0,q:"What is the maximum execution timeout for a single AWS Lambda function invocation?",o:["15 minutes","5 minutes","30 minutes","60 minutes"],e:"Lambda functions can run for up to 900 seconds. Longer jobs belong in Step Functions, ECS/Fargate, or AWS Batch."},
{d:0,q:"Amazon S3 invokes a Lambda function when an object is uploaded. Which invocation type does S3 use?",o:["Asynchronous (Event)","Synchronous (RequestResponse)","Polling by the Lambda service","Streaming"],e:"S3 event notifications invoke Lambda asynchronously. Lambda queues the event and retries on error."},
{d:0,q:"A Lambda function processes messages from an SQS standard queue, and some messages fail repeatedly. Where should the dead-letter queue be configured?",o:["On the source SQS queue using a redrive policy","In the function's asynchronous invocation settings","On the Lambda execution role","On the CloudWatch alarm"],e:"For SQS event sources Lambda polls the queue, so failed messages return to the queue. The DLQ belongs on the queue (maxReceiveCount). A function-level DLQ applies only to asynchronous invocations."},
{d:0,q:"An application performs 10 strongly consistent reads per second of 8 KB items. How many read capacity units (RCUs) are required?",o:["20","10","40","5"],e:"One RCU is one strongly consistent read per second of up to 4 KB. An 8 KB item needs 2 RCUs per read, so 10 x 2 = 20."},
{d:0,q:"An application performs 40 eventually consistent reads per second of 4 KB items. How many RCUs are required?",o:["20","40","10","80"],e:"One RCU provides two eventually consistent reads per second of up to 4 KB, so 40 / 2 = 20."},
{d:0,q:"An application writes 5 items per second to DynamoDB, each 2.5 KB. How many write capacity units (WCUs) are required?",o:["15","5","13","10"],e:"One WCU is one write per second of up to 1 KB. 2.5 KB rounds up to 3 WCUs per item, so 5 x 3 = 15."},
{d:0,q:"A DynamoDB table already contains data. A developer needs to query by an attribute that is not the partition key. Which index can be added now?",o:["Global secondary index (GSI)","Local secondary index (LSI)","A second partition key on the base table","DynamoDB Accelerator (DAX)"],e:"GSIs can be created at any time and can use a different partition and sort key. LSIs must be defined when the table is created and share the table's partition key."},
{d:0,q:"Which choice of DynamoDB partition key best distributes traffic evenly?",o:["A high-cardinality attribute such as user ID","A boolean flag","A constant value","The status of an order with three possible values"],e:"High-cardinality keys spread requests across partitions and avoid hot partitions."},
{d:0,q:"Which feature captures a time-ordered sequence of item-level changes in a DynamoDB table so a Lambda function can react to them?",o:["DynamoDB Streams","DynamoDB TTL","DynamoDB Accelerator (DAX)","Global tables"],e:"Streams record item changes for 24 hours and can trigger Lambda."},
{d:0,q:"How can session items be deleted automatically from a DynamoDB table after they expire, without consuming write capacity?",o:["Enable TTL on an attribute holding an expiry timestamp","Run a scheduled Lambda that scans and deletes","Use conditional writes","Create a global secondary index"],e:"TTL removes expired items in the background and the deletes do not consume WCUs."},
{d:0,q:"Two clients may update the same DynamoDB item at the same time. Which technique prevents one from silently overwriting the other?",o:["Conditional writes using a version attribute (optimistic locking)","Eventually consistent reads","Batch writes","Increasing provisioned WCUs"],e:"A ConditionExpression on a version number makes the second writer fail so it can retry with fresh data."},
{d:0,q:"Which DynamoDB operation is the most efficient way to retrieve all items that share a partition key?",o:["Query","Scan","Export to S3","BatchGetItem without keys"],e:"Query reads only items matching the key condition. Scan reads the entire table."},
{d:0,q:"A developer must update items in two DynamoDB tables so that either both updates succeed or neither does. Which API should be used?",o:["TransactWriteItems","BatchWriteItem","Two sequential UpdateItem calls","Scan with a filter"],e:"TransactWriteItems provides all-or-nothing, ACID writes across items and tables."},
{d:0,q:"A new application has unpredictable DynamoDB traffic, and the team does not want to manage capacity. Which capacity mode fits?",o:["On-demand","Provisioned with a fixed number of RCUs and WCUs","Provisioned with reserved capacity","Provisioned with DAX"],e:"On-demand mode scales automatically and bills per request."},
{d:0,q:"A DynamoDB Query response includes a LastEvaluatedKey. What does it mean?",o:["More results are available; pass it as ExclusiveStartKey in the next request","The query failed and must be retried","The table is being throttled","The item is locked by another client"],e:"Responses are paginated at 1 MB, and LastEvaluatedKey is the cursor for the next page."},
{d:0,q:"What does the visibility timeout of an Amazon SQS message control?",o:["How long a received message stays hidden from other consumers","How long the message is retained in the queue","How long a producer waits before sending","How long long-polling waits for messages"],e:"If the consumer does not delete the message before the timeout expires, it becomes visible again."},
{d:0,q:"Which SQS setting reduces empty responses and cost by waiting for messages to arrive?",o:["Long polling (WaitTimeSeconds greater than 0)","Short polling","A shorter visibility timeout","A delay queue"],e:"Long polling waits up to 20 seconds for a message before returning."},
{d:0,q:"Which SQS queue type preserves message order within a message group and supports deduplication?",o:["FIFO queue","Standard queue","Delay queue","Dead-letter queue"],e:"FIFO queues order messages per MessageGroupId. Standard queues offer at-least-once delivery with best-effort ordering."},
{d:0,q:"One order event must be delivered to several independent systems, each with its own durable queue. Which pattern fits?",o:["Publish to an SNS topic with multiple SQS queue subscriptions","Use one SQS queue with multiple consumers","Write the event to S3","Use Route 53 weighted records"],e:"SNS to SQS fan-out lets each subscriber process every message independently."},
{d:0,q:"Which type of API Gateway API is lower cost and lower latency for simple Lambda or HTTP proxying, with fewer features than REST APIs?",o:["HTTP API","REST API","Private REST API","WebSocket API"],e:"HTTP APIs are cheaper and faster, while REST APIs offer more features such as API keys, usage plans, and request validation."},
{d:0,q:"With API Gateway Lambda proxy integration, what must the Lambda function return?",o:["A JSON object with statusCode, headers, and body","Any plain string","An XML document","Nothing; API Gateway builds the response"],e:"A malformed response from the function causes a 502 Bad Gateway."},
{d:0,q:"A developer needs to upload a 6 GB file to Amazon S3. What is required?",o:["Multipart upload","A single PUT request","S3 Select","A presigned POST only"],e:"A single PUT is limited to 5 GB. Multipart upload is recommended for objects over 100 MB."},
{d:0,q:"Which AWS Step Functions workflow type supports executions that run for up to one year?",o:["Standard","Express","Both types equally","Neither type"],e:"Standard workflows run up to a year with exactly-once execution. Express workflows run up to 5 minutes and suit high-volume event processing."},
{d:0,q:"Which service lets you trigger a Lambda function on a cron or rate schedule?",o:["Amazon EventBridge","Amazon SQS","AWS Config","Amazon Macie"],e:"EventBridge rules and Scheduler support cron and rate expressions."},
{d:0,q:"In Amazon Kinesis Data Streams, where is record ordering guaranteed?",o:["Within a shard","Across the entire stream","Across all shards in a Region","Ordering is never guaranteed"],e:"Records with the same partition key go to the same shard and are ordered by sequence number."},
{d:0,q:"In Amazon ECS, which role gives the application code inside a container permission to call AWS services such as S3?",o:["Task role","Task execution role","EC2 instance service-linked role","Root user"],e:"The task role is for your application. The task execution role lets the ECS agent pull images and write logs."},
{d:0,q:"How can several Lambda functions share the same library dependencies without bundling them into each deployment package?",o:["Lambda layers","Environment variables","Aliases","Function URLs"],e:"Layers package shared code or dependencies that functions attach at runtime."},
{d:0,q:"How can a developer increase the CPU power available to a Lambda function?",o:["Increase the memory setting","Choose a larger instance type","Add vCPUs in the configuration","Increase the timeout"],e:"Lambda allocates CPU in proportion to configured memory."},
{d:0,q:"A Lambda function needs to write temporary files while it runs. Where can it write?",o:["/tmp (512 MB by default, configurable up to 10 GB)","Any directory in the filesystem","The deployment package directory","/var/www"],e:"Only /tmp is writable, and the data does not persist across execution environments."},
{d:0,q:"A Lambda function must access an Amazon RDS database in a private subnet. What is required?",o:["Configure the function with VPC subnets and security groups","Assign a public IP address to the function","Attach an internet gateway to the function","Use AWS Direct Connect"],e:"A VPC-enabled function gets network interfaces in your subnets and is governed by security groups."},
{d:0,q:"Which Lambda feature provides a dedicated HTTPS endpoint for a function without using API Gateway?",o:["Function URL","Layer","Alias","Destination"],e:"A function URL is a built-in HTTPS endpoint with IAM or no authentication."},
{d:0,q:"Which TWO are event sources that Lambda polls through an event source mapping?",o:["Amazon SQS","Amazon Kinesis Data Streams","Amazon S3","Amazon SNS"],ma:[0,1],e:"Lambda polls SQS, Kinesis, and DynamoDB Streams. S3 and SNS push events to Lambda."},
{d:0,q:"Which TWO statements about Amazon DynamoDB are true?",o:["Data is automatically replicated across multiple Availability Zones","All tables are encrypted at rest","Tables must be created inside a VPC","All attributes must be defined before inserting items"],ma:[0,1],e:"DynamoDB is regional and highly available by default and always encrypts at rest. It is schemaless apart from the key attributes and is accessed through a public endpoint or VPC endpoints."},
{d:0,q:"What is the maximum size of a single item in Amazon DynamoDB?",o:["400 KB","1 MB","4 KB","256 KB"],e:"Items, including attribute names and values, cannot exceed 400 KB. Store larger objects in S3 and keep a pointer in the item."},
{d:0,q:"A developer must write 60 items to a DynamoDB table using BatchWriteItem. What is the minimum number of calls required?",o:["3","1","2","6"],e:"BatchWriteItem accepts up to 25 put or delete requests per call, so 60 items need at least three calls. Unprocessed items must be retried."},
{d:0,q:"Many clients increment a page-view count stored in a DynamoDB item at the same time. How should the developer update it without a read-modify-write cycle?",o:["UpdateItem with an update expression such as SET views = views + :inc","GetItem, add one in code, then PutItem","Scan the table and rewrite the item","BatchWriteItem with the new value"],e:"An update expression applies the increment atomically on the server, so concurrent updates are not lost."},
{d:0,q:"A developer queries a DynamoDB global secondary index with ConsistentRead set to true. What happens?",o:["The request fails because GSIs support only eventually consistent reads","The request returns strongly consistent data","The request is billed at double the rate","The request is routed to the base table"],e:"GSIs are updated asynchronously and support only eventually consistent reads. Local secondary indexes can serve strongly consistent reads."},
{d:0,q:"An application needs a DynamoDB table that accepts writes in multiple AWS Regions and replicates changes between them. Which feature provides this?",o:["Global tables","DynamoDB Streams alone","Cross-Region read replicas","DynamoDB Accelerator (DAX)"],e:"Global tables are fully managed, multi-Region, multi-active replication."},
{d:0,q:"How far back can point-in-time recovery (PITR) restore a DynamoDB table?",o:["Up to 35 days","Up to 24 hours","Up to 7 days","Up to 1 year"],e:"PITR keeps continuous backups for a configurable period of 1 to 35 days."},
{d:0,q:"A PutItem call must fail if an item with the same partition key (attribute pk) already exists. Which condition expression achieves this?",o:["attribute_not_exists(pk)","attribute_exists(pk)","size(pk) > 0","contains(pk, :val)"],e:"attribute_not_exists on the key attribute makes the write succeed only when no item with that key exists."},
{d:0,q:"A user deletes an object from an S3 bucket that has versioning enabled, without specifying a version ID. What happens?",o:["S3 adds a delete marker and keeps the previous versions","The object and all versions are permanently deleted","The request fails with an error","Only the oldest version is deleted"],e:"A simple delete in a versioned bucket inserts a delete marker. Specifying a version ID deletes that version permanently."},
{d:0,q:"A developer overwrites an existing S3 object and immediately reads it back. What does S3 return?",o:["The latest version of the object","Possibly the old version, because of eventual consistency","An error until replication completes","The old version for 15 minutes"],e:"S3 provides strong read-after-write consistency for PUT and DELETE requests in all Regions."},
{d:0,q:"A single-page app served from https://app.example.com loads images from an S3 bucket in the browser, and the requests are blocked. Which fix is needed?",o:["Add a CORS configuration to the bucket that allows the app's origin","Enable S3 versioning","Turn on Transfer Acceleration","Add a lifecycle rule"],e:"Browsers enforce cross-origin rules, so the bucket must return CORS headers for the allowed origin and methods."},
{d:0,q:"Objects in an S3 bucket should move to S3 Glacier Flexible Retrieval 90 days after creation, automatically. What should be configured?",o:["An S3 Lifecycle rule","An S3 event notification","A bucket policy","S3 Object Lock"],e:"Lifecycle rules transition or expire objects based on age."},
{d:0,q:"Which TWO destinations can Amazon S3 event notifications send events to directly?",o:["AWS Lambda","Amazon SQS","Amazon Kinesis Data Streams","AWS Step Functions","Amazon DynamoDB"],ma:[0,1],e:"S3 notifications go to Lambda, SQS, SNS, or EventBridge."},
{d:0,q:"Messages sent by a producer should become available to consumers only after 10 minutes. Which SQS feature does this?",o:["Delay queue (DelaySeconds)","Visibility timeout","Long polling","Dead-letter queue"],e:"A delay queue hides new messages for up to 15 minutes. Visibility timeout hides messages after a consumer receives them."},
{d:0,q:"By default, how long does Amazon SQS retain an unprocessed message?",o:["4 days","1 day","14 days","30 days"],e:"The default retention period is 4 days and can be set from 60 seconds to 14 days."},
{d:0,q:"An application must send payloads larger than the SQS maximum message size. Which approach is recommended?",o:["Store the payload in S3 and send a reference using the SQS Extended Client Library","Send the payload to a dead-letter queue","Split the payload across Regions","Increase the visibility timeout"],e:"The Extended Client Library stores large payloads in S3 and passes a pointer through the queue."},
{d:0,q:"A FIFO queue producer retries a send after a network timeout. How does SQS avoid creating a duplicate message?",o:["It uses the MessageDeduplicationId within the 5-minute deduplication interval","It uses the receipt handle","It uses the visibility timeout","It deletes the older message after 1 hour"],e:"FIFO queues drop messages that repeat a deduplication ID within five minutes. Content-based deduplication can generate the ID from a hash of the body."},
{d:0,q:"Only some of the messages published to an SNS topic should reach a given SQS subscriber, based on a message attribute. Which feature should be used?",o:["A subscription filter policy","A queue redrive policy","A topic access policy","Message delay"],e:"Filter policies deliver a message to a subscription only if its attributes match."},
{d:0,q:"Which service loads streaming data into Amazon S3, Amazon Redshift, or OpenSearch Service without writing consumer code?",o:["Amazon Data Firehose (formerly Kinesis Data Firehose)","Amazon Kinesis Data Streams","Amazon SQS","AWS Step Functions"],e:"Firehose buffers and delivers streaming data to destinations automatically. Data Streams requires you to build consumers."},
{d:0,q:"What is the default data retention period of an Amazon Kinesis data stream?",o:["24 hours","7 days","1 hour","365 days"],e:"The default is 24 hours, extendable up to 365 days."},
{d:0,q:"A Lambda function processes batches from a Kinesis stream, and one bad record causes the whole batch to be retried. Which setting lets Lambda retry only the failed records?",o:["ReportBatchItemFailures (partial batch response)","Reserved concurrency","Provisioned concurrency","A larger batch size"],e:"With partial batch responses the function returns the IDs of failed items, and only those are retried."},
{d:0,q:"A Lambda function connects to a database on every invocation, which is slow. What is the recommended change?",o:["Create the connection outside the handler so warm invocations can reuse it","Create the connection inside the handler on each call","Increase the function timeout","Disable the VPC configuration"],e:"Code outside the handler runs once per execution environment and is reused across warm invocations."},
{d:0,q:"Which Lambda feature reduces cold-start latency by restoring from a cached snapshot of an initialized execution environment?",o:["Lambda SnapStart","Reserved concurrency","Lambda layers","Function URLs"],e:"SnapStart caches a snapshot after initialization. It was introduced for Java and is offered for additional runtimes."},
{d:0,q:"A company sells API access and wants to limit each customer to a set request rate and a monthly quota. Which API Gateway features should be used together?",o:["API keys with usage plans","Cognito groups with IAM roles","Stage variables with canary releases","Resource policies with WAF"],e:"Usage plans attach throttling and quota limits to API keys. They are for metering and are not an authentication mechanism."},
{d:0,q:"With a non-proxy integration, API Gateway must convert a JSON request into a different format before calling the backend. Which feature does this?",o:["Mapping templates (Velocity Template Language)","Stage variables","Usage plans","Authorizers"],e:"Mapping templates transform request and response payloads for non-proxy integrations."},
{d:0,q:"A chat application needs two-way, persistent communication between clients and a backend. Which API Gateway API type fits?",o:["WebSocket API","REST API","HTTP API","Private REST API"],e:"WebSocket APIs keep connections open so the server can push messages to clients."},
{d:0,q:"How can a Step Functions state machine retry a failed Task state and then route to a fallback state if the retries fail?",o:["Define Retry and Catch fields on the state","Add a second Lambda function that polls for errors","Use a Wait state","Use a Parallel state"],e:"Retry sets backoff behavior for specified errors, and Catch redirects to another state when errors persist."},
{d:0,q:"Which Step Functions state runs the same steps for each item in an array?",o:["Map","Choice","Pass","Wait"],e:"A Map state iterates over the items of an input array."},
{d:0,q:"In Amazon ECS, which resource describes the container image, CPU, memory, and port mappings for an application?",o:["Task definition","Service","Cluster","Capacity provider"],e:"A task definition is the blueprint. A service keeps a desired number of tasks running."},
{d:0,q:"Which AWS service provides a managed GraphQL API that can fetch data from DynamoDB, Lambda, and HTTP sources?",o:["AWS AppSync","Amazon API Gateway REST API","Amazon Cognito","AWS Amplify Hosting"],e:"AppSync resolves GraphQL queries against multiple data sources and supports real-time subscriptions."},
{d:0,q:"A Lambda function opens many connections to an Amazon RDS database during traffic spikes and exhausts the database's connection limit. What should the developer use?",o:["Amazon RDS Proxy","A larger Lambda memory setting","Amazon S3 Transfer Acceleration","AWS Direct Connect"],e:"RDS Proxy pools and shares database connections between function invocations."},
{d:0,q:"Which feature is available in ElastiCache for Redis but not in ElastiCache for Memcached?",o:["Replication and persistence with data structures such as sorted sets","Multithreaded architecture","Simple key-value caching","Horizontal scaling by adding nodes"],e:"Redis supports replication, persistence, and rich data types. Memcached is simpler and multithreaded."},
{d:0,q:"A team wants to re-process past events after fixing a bug in a consumer. Which Amazon EventBridge feature helps?",o:["Event archive and replay","Dead-letter queues only","Schema registry","Input transformers"],e:"EventBridge can archive events on a bus and replay them to the same bus later."},
{d:0,q:"A DynamoDB Query returns a lot of data, but the code needs only two attributes of each item. Which parameter limits the returned attributes?",o:["ProjectionExpression","FilterExpression","KeyConditionExpression","ConditionExpression"],e:"ProjectionExpression selects the attributes to return. Read capacity is still based on the size of the items read, not the projected size."},
{d:0,q:"A script calls an AWS API that returns paged results and must process every page. What is the recommended SDK approach?",o:["Use the SDK's paginator, or follow the continuation token until it is absent","Call the API once and assume it returned everything","Increase the instance size","Use a larger request timeout"],e:"Paginated APIs return a continuation token. Paginators handle that loop for you."},
{d:0,q:"Which AWS CLI option filters the JSON output on the client using JMESPath?",o:["--query","--filter","--output-filter","--where"],e:"--query applies a JMESPath expression to the CLI output. Server-side filtering uses options such as --filters on some commands."},

// ---------- Domain 1: Security ----------
{d:1,q:"How can a developer let a mobile user upload one file directly to a private S3 bucket without giving the user AWS credentials?",o:["Generate a presigned URL","Make the bucket public","Share the developer's access keys","Create an IAM user per mobile user"],e:"A presigned URL grants temporary access to a specific object and operation using the signer's permissions."},
{d:1,q:"A presigned URL is generated by a Lambda function using its execution role. When does the URL stop working?",o:["When it expires or when the role's temporary credentials expire, whichever comes first","Never","After a single use","Always after 24 hours"],e:"A presigned URL is limited by both its configured expiry and the lifetime of the credentials that signed it."},
{d:1,q:"An application running on Amazon EC2 needs to read from S3. What is the most secure way to provide credentials?",o:["Attach an IAM role through an instance profile","Store access keys in the application configuration file","Embed access keys in the AMI","Use the root user's access keys"],e:"Roles supply short-lived credentials that rotate automatically."},
{d:1,q:"A developer must call AWS APIs from a local workstation. What is the recommended approach?",o:["Use temporary credentials, for example through IAM Identity Center and a CLI profile","Hard-code long-term access keys in source code","Share one IAM user among the team","Use the root user's access keys"],e:"Temporary credentials reduce the risk of leaked long-term keys."},
{d:1,q:"A user in Account B needs to use a role in Account A. Which API call returns temporary credentials for it?",o:["sts:AssumeRole","iam:CreateUser","kms:Decrypt","sts:GetCallerIdentity"],e:"The role's trust policy must trust Account B, and the caller needs permission to call sts:AssumeRole."},
{d:1,q:"An IAM user has a policy that allows s3:* and another policy that explicitly denies s3:DeleteObject. What happens when the user deletes an object?",o:["The request is denied","The request is allowed","It is allowed if the user has MFA","It depends on the policy order"],e:"An explicit deny always overrides any allow."},
{d:1,q:"How do you allow Amazon S3 to invoke a Lambda function?",o:["Add a resource-based policy to the function","Attach S3 full access to the function's execution role","Add an inline policy to the bucket owner's IAM user","Make the function public"],e:"The execution role controls what the function can do. The resource-based policy controls who can invoke it."},
{d:1,q:"Which Amazon Cognito component handles sign-up and sign-in and issues JSON Web Tokens (JWTs)?",o:["User pool","Identity pool","Cognito Sync","User pool app client secret"],e:"User pools are user directories that authenticate users and issue tokens."},
{d:1,q:"Which Amazon Cognito component exchanges tokens from a user pool or a social identity provider for temporary AWS credentials?",o:["Identity pool","User pool","Lambda authorizer","Hosted UI"],e:"Identity pools (federated identities) vend temporary AWS credentials through STS."},
{d:1,q:"A REST API must validate custom bearer tokens issued by a third-party identity provider using custom logic. Which API Gateway feature fits?",o:["Lambda authorizer","Cognito user pool authorizer","API keys","Usage plans"],e:"A Lambda authorizer runs your code to validate a token and returns an IAM policy. API keys are for metering, not authentication."},
{d:1,q:"A developer must encrypt a 50 MB file using AWS KMS. A direct Encrypt call accepts only 4 KB. Which approach should be used?",o:["Envelope encryption using GenerateDataKey","Split the file into 4 KB pieces and call Encrypt for each","Use SSE-C","Store the file unencrypted"],e:"KMS generates a data key. The data key encrypts the file locally, and the encrypted data key is stored with it."},
{d:1,q:"Which Amazon S3 encryption option provides an audit trail of key usage in AWS CloudTrail and supports key policies?",o:["SSE-KMS","SSE-S3","SSE-C","No encryption"],e:"SSE-KMS calls to KMS are logged in CloudTrail and governed by key policies."},
{d:1,q:"Which service provides built-in automatic rotation of database credentials?",o:["AWS Secrets Manager","AWS Systems Manager Parameter Store","AWS KMS","AWS Config"],e:"Secrets Manager rotates secrets with Lambda (built in for RDS). Parameter Store SecureString stores encrypted values but has no native rotation."},
{d:1,q:"Which service stores configuration values and encrypted strings hierarchically, with no charge for standard parameters?",o:["AWS Systems Manager Parameter Store","AWS Secrets Manager","AWS CloudHSM","AWS Certificate Manager"],e:"Parameter Store is free for standard parameters and supports SecureString using KMS."},
{d:1,q:"A developer stores a database password in a Lambda environment variable. What most improves security?",o:["Store it in Secrets Manager and retrieve it at runtime with IAM permission","Base64 encode the value","Rename the variable","Commit the value to the repository"],e:"Secrets Manager centralizes, audits, and rotates secrets. Base64 is encoding, not encryption."},
{d:1,q:"Which statement about Amazon DynamoDB encryption at rest is true?",o:["All tables are encrypted at rest by default","It must be enabled on each table","It requires AWS CloudHSM","It is not supported"],e:"DynamoDB always encrypts at rest, using AWS owned, AWS managed, or customer managed keys."},
{d:1,q:"Which S3 bucket policy condition denies any request that does not use TLS?",o:["aws:SecureTransport equal to false","aws:MultiFactorAuthPresent","s3:x-amz-acl","aws:SourceIp"],e:"A Deny statement with Bool aws:SecureTransport false blocks plain HTTP requests."},
{d:1,q:"A developer gets AccessDenied when creating a Lambda function and assigning it an execution role. Which permission is most likely missing?",o:["iam:PassRole","lambda:InvokeFunction","sts:GetSessionToken","kms:Decrypt"],e:"To assign a role to a service, the caller needs iam:PassRole for that role."},
{d:1,q:"Which IAM feature sets the maximum permissions that identity-based policies can grant to a user or role?",o:["Permissions boundary","Resource-based policy","Session tag","Instance profile"],e:"The effective permissions are the intersection of the identity policy and the boundary."},
{d:1,q:"Which tool can generate a least-privilege IAM policy based on CloudTrail activity?",o:["IAM Access Analyzer policy generation","AWS Trusted Advisor","Amazon Inspector","AWS Artifact"],e:"Access Analyzer reviews access activity in CloudTrail and builds a policy for what was actually used."},
{d:1,q:"How are requests authenticated when calling AWS APIs directly over HTTP?",o:["Signature Version 4 (SigV4) signing","Basic authentication with a username and password","API keys issued by S3","OAuth tokens from CloudWatch"],e:"The SDKs and CLI sign requests with SigV4 automatically."},
{d:1,q:"A developer wants to run custom validation before a new Cognito user is created. Which feature should be used?",o:["Pre sign-up Lambda trigger","Post confirmation Lambda trigger","Identity pool role mapping","Hosted UI customization"],e:"The pre sign-up trigger can accept, reject, or auto-confirm a registration."},
{d:1,q:"Which resource must exist for every AWS KMS key to control who can use it?",o:["Key policy","IAM group","Security group","Bucket ACL"],e:"Every KMS key has a key policy. IAM policies only apply if the key policy allows them."},
{d:1,q:"Which TWO methods avoid hard-coding AWS credentials in application code?",o:["Use IAM roles attached to the compute resource","Retrieve temporary credentials from AWS STS","Hard-code access keys in constants","Store root access keys in a config file"],ma:[0,1],e:"Roles and STS provide short-lived credentials. Long-term keys in code or config risk exposure."},
{d:1,q:"Which TWO services can an application use to retrieve secrets at runtime?",o:["AWS Secrets Manager","AWS Systems Manager Parameter Store","Amazon SQS","Amazon CloudFront"],ma:[0,1],e:"Both store secrets securely, and access is controlled by IAM."},
{d:1,q:"A company serves private video files through Amazon CloudFront and wants only subscribers to access them for a limited time. What should the developer use?",o:["CloudFront signed URLs or signed cookies","An S3 bucket ACL set to public-read","A larger CloudFront price class","Route 53 geolocation routing"],e:"Signed URLs and cookies restrict who can access content and for how long."},
{d:1,q:"Which S3 feature prevents any public access across an entire account regardless of individual bucket policies and ACLs?",o:["S3 Block Public Access","S3 Object Lock","S3 Versioning","S3 Intelligent-Tiering"],e:"Block Public Access can be applied at the bucket or account level and overrides permissive policies and ACLs."},
{d:1,q:"A role in Account A must read a bucket in Account B. Which setup grants access?",o:["Allow the role in the bucket policy of Account B and ensure the role's identity policy allows the S3 actions","Create an IAM user in Account B and share its access keys","Share the root credentials of Account B","Make the bucket public"],e:"For cross-account access, both sides must allow it: the resource policy in the owning account and the identity policy in the calling account."},
{d:1,q:"An IAM user has no policies attached. What is the result of a request to list S3 buckets?",o:["Denied, because everything is denied by default","Allowed, because the user is in the account","Allowed for read-only actions","Allowed if made from the console"],e:"IAM denies all requests by default until a policy explicitly allows them."},
{d:1,q:"What does the trust policy of an IAM role define?",o:["Which principals can assume the role","Which actions the role can perform","Which Regions the role can be used in","The password policy for the role"],e:"The trust policy names who can assume the role. Permission policies define what the role can do."},
{d:1,q:"A mobile app has an OpenID Connect token from a web identity provider. Which STS API returns temporary AWS credentials for it?",o:["AssumeRoleWithWebIdentity","GetCallerIdentity","AssumeRoleWithSAML","DecodeAuthorizationMessage"],e:"AssumeRoleWithWebIdentity exchanges an OIDC token for temporary credentials. Amazon Cognito identity pools are the recommended wrapper."},
{d:1,q:"Which statement about AWS KMS keys is true?",o:["Customer managed keys let you control the key policy, rotation, and when a key is disabled","AWS managed keys let you edit the key policy","AWS owned keys appear in your KMS console and CloudTrail logs","Keys can be exported in plaintext"],e:"Customer managed keys give the most control. AWS managed keys are created for you by services, and AWS owned keys are not visible in your account."},
{d:1,q:"Which statement about AWS Lambda environment variables is true?",o:["They are encrypted at rest by default","They are stored in plaintext in the function code","They can exceed 4 KB in total","They cannot be read by the function"],e:"Variables are encrypted at rest. For extra protection, use a customer managed key and encrypt sensitive values client-side, or store them in Secrets Manager."},
{d:1,q:"After a user signs in, an app needs to read the user's email and name claims from a Cognito user pool token. Which token carries identity claims about the user?",o:["ID token","Access token","Refresh token","Identity pool token"],e:"The ID token carries user attributes. The access token authorizes API calls, and the refresh token obtains new tokens."},
{d:1,q:"Which OAuth 2.0 flow is recommended for a server-side web app that uses the Cognito hosted UI?",o:["Authorization code grant","Implicit grant","Client credentials grant","Resource owner password grant"],e:"The authorization code grant keeps tokens out of the browser URL and supports PKCE for public clients."},
{d:1,q:"An API Gateway REST API must accept requests only from a specific set of IP address ranges. Which feature does this?",o:["A resource policy on the API","A usage plan","A stage variable","A mapping template"],e:"Resource policies can allow or deny based on source IP, VPC, or account."},
{d:1,q:"Clients call an API Gateway API using AWS credentials. Which authorization type should be enabled?",o:["AWS_IAM authorization with SigV4-signed requests","An API key only","A mapping template","Stage variables"],e:"IAM authorization checks the caller's signed request against IAM policies."},
{d:1,q:"An Application Load Balancer must authenticate users with an OIDC identity provider before forwarding requests. What should be configured?",o:["An authenticate action on the listener rule","A Lambda layer","An API Gateway usage plan","A security group rule"],e:"ALB can authenticate users through Amazon Cognito or any OIDC-compliant provider."},
{d:1,q:"Which service can block SQL injection and cross-site scripting requests before they reach an API Gateway REST API stage or an Application Load Balancer?",o:["AWS WAF","AWS Shield Standard","Amazon Macie","AWS Artifact"],e:"WAF can be associated with API Gateway REST API stages, ALBs, and CloudFront distributions."},
{d:1,q:"Which service issues and renews public TLS certificates that can be attached to a CloudFront distribution or an Application Load Balancer?",o:["AWS Certificate Manager (ACM)","AWS KMS","AWS Secrets Manager","AWS CloudHSM"],e:"ACM provisions and automatically renews certificates for integrated services."},
{d:1,q:"With S3 server-side encryption using customer-provided keys (SSE-C), what must the client do on each request?",o:["Provide the encryption key over HTTPS","Nothing; S3 stores the key","Upload the key to KMS first","Use a presigned URL only"],e:"S3 does not store the SSE-C key, so it must be sent with each request, and only over HTTPS."},
{d:1,q:"A company must ensure every object uploaded to a bucket is encrypted with SSE-KMS. How can the bucket enforce this?",o:["A bucket policy that denies PutObject requests without the required x-amz-server-side-encryption header","A lifecycle rule","A CORS rule","S3 Transfer Acceleration"],e:"A deny condition on the encryption header rejects non-compliant uploads. Default bucket encryption can also be configured."},
{d:1,q:"Each user of a mobile app should access only the DynamoDB items whose partition key matches their own ID. Which IAM policy condition key enforces this?",o:["dynamodb:LeadingKeys","dynamodb:Select","aws:SourceIp","s3:prefix"],e:"LeadingKeys restricts access to items whose partition key matches the specified values, such as the Cognito identity ID."},
{d:1,q:"A SaaS provider assumes roles in customer accounts and wants to prevent the confused deputy problem. What should the trust policy require?",o:["An external ID","MFA on the root user","A longer session duration","An IP address allow list only"],e:"A unique external ID shared with the customer ensures the provider assumes the role only on that customer's behalf."},
{d:1,q:"A company wants Amazon ECR to identify known software vulnerabilities in container images as they are pushed. What should the developer enable?",o:["Image scanning on push","A lifecycle policy","Cross-Region replication","Tag immutability"],e:"ECR image scanning reports known CVEs. Tag immutability prevents tags from being overwritten."},
{d:1,q:"A CodeBuild project needs a database password at build time without storing it in the buildspec. What is the recommended approach?",o:["Reference a Secrets Manager or Parameter Store value in the buildspec env section","Commit the password to the repository","Pass it as a plaintext environment variable","Print it in the build log"],e:"CodeBuild can resolve parameter-store and secrets-manager values into environment variables at runtime."},
{d:1,q:"A private application running in a VPC reads from DynamoDB and must not send traffic over the internet. What should be created?",o:["A gateway VPC endpoint for DynamoDB","An internet gateway","A NAT instance","A public IP for the table"],e:"Gateway endpoints for S3 and DynamoDB keep traffic on the AWS network and have no additional charge."},
{d:1,q:"A mobile app must let users who are not signed in upload crash logs to S3 with minimal permissions. Which Cognito feature supports this?",o:["Unauthenticated (guest) access in an identity pool with a restricted role","A user pool with MFA required","The root user's access keys","A public bucket"],e:"Identity pools can issue credentials for guests, mapped to an IAM role with limited permissions."},
{d:1,q:"Each signed-in user should read and write only the S3 prefix named after their Cognito identity ID. Which technique does this in a single policy?",o:["IAM policy variables such as ${cognito-identity.amazonaws.com:sub} in the resource ARN","One IAM role per user","A separate bucket per user","Disabling IAM"],e:"Policy variables are replaced at request time, so one policy scopes each user to their own prefix."},
{d:1,q:"Which TWO measures protect data stored in Amazon S3 at rest?",o:["Server-side encryption with SSE-S3 or SSE-KMS","Client-side encryption before upload","Enabling CORS","Enabling Transfer Acceleration","Using a longer bucket name"],ma:[0,1],e:"Server-side and client-side encryption both protect data at rest. CORS and acceleration are unrelated."},
{d:1,q:"Which TWO are recommended ways to provide credentials to an application running on AWS compute?",o:["An IAM role for EC2, ECS tasks, or Lambda","Temporary credentials from AWS STS","Access keys stored in the source repository","Access keys baked into an AMI","The root user's access keys"],ma:[0,1],e:"Roles and STS deliver short-lived credentials with no secrets to manage in code."},
{d:1,q:"Why must a Lambda function's execution role include permissions such as logs:CreateLogStream and logs:PutLogEvents?",o:["So the function can write logs to CloudWatch Logs","So the function can read from S3","So API Gateway can invoke it","So the function can be deployed"],e:"Without those permissions, invocations succeed but no logs appear. The managed policy AWSLambdaBasicExecutionRole grants them."},

// ---------- Domain 2: Deployment ----------
{d:2,q:"Which section is the only required section in an AWS CloudFormation template?",o:["Resources","Parameters","Outputs","Mappings"],e:"Every template must declare at least one resource."},
{d:2,q:"Which declaration marks a CloudFormation template as an AWS SAM template?",o:["Transform: AWS::Serverless-2016-10-31","AWSTemplateFormatVersion: sam","Type: SAM::Application","Include: sam.yaml"],e:"The SAM transform expands serverless resource types into standard CloudFormation resources."},
{d:2,q:"Which commands build and deploy an AWS SAM application?",o:["sam build, then sam deploy","sam init, then sam delete","sam local invoke, then sam logs","aws s3 sync, then aws lambda update-function-code"],e:"sam build compiles and packages the app, and sam deploy creates or updates the CloudFormation stack."},
{d:2,q:"Which CloudFormation feature lets you preview how changes will affect running resources before executing them?",o:["Change sets","Drift detection","Stack policies","Nested stacks"],e:"A change set lists what will be added, modified, or replaced."},
{d:2,q:"How can one CloudFormation stack use a value exported by another stack?",o:["Fn::ImportValue","Ref to the other stack's resource","Fn::Join","Fn::Sub with the stack name"],e:"Exports are consumed in other stacks of the same Region with Fn::ImportValue."},
{d:2,q:"Which resource attribute keeps an RDS database or S3 bucket when its CloudFormation stack is deleted?",o:["DeletionPolicy: Retain","UpdatePolicy","CreationPolicy","DependsOn"],e:"DeletionPolicy controls what happens to a resource on stack deletion (Retain, Snapshot, Delete)."},
{d:2,q:"Which CloudFormation feature detects whether resources were changed outside of CloudFormation?",o:["Drift detection","Change sets","StackSets","Rollback triggers"],e:"Drift detection compares actual resource configuration to the template."},
{d:2,q:"Which file defines how AWS CodeDeploy deploys an application to EC2 instances, including lifecycle hooks?",o:["appspec.yml","buildspec.yml","template.yaml","Dockerfile"],e:"The AppSpec file maps files to destinations and runs scripts at lifecycle events."},
{d:2,q:"Which file defines the commands that AWS CodeBuild runs during a build?",o:["buildspec.yml","appspec.yml","pipeline.json","serverless.yml"],e:"buildspec.yml defines phases such as install, pre_build, build, and post_build plus artifacts."},
{d:2,q:"Which CodeDeploy configuration for Lambda shifts 10 percent of traffic to the new version and the rest after 5 minutes if no alarms fire?",o:["Canary10Percent5Minutes","Linear10PercentEvery1Minute","AllAtOnce","In-place"],e:"Canary shifts traffic in two steps. Linear shifts in equal increments at fixed intervals."},
{d:2,q:"How can you send 10 percent of a Lambda function's traffic to a new version for testing?",o:["Weighted alias routing between two versions","Raise reserved concurrency","Edit $LATEST in place","Deploy in another Region"],e:"An alias can split traffic between two published versions."},
{d:2,q:"What happens when you publish a Lambda function version?",o:["It creates an immutable snapshot of the code and configuration","It deletes $LATEST","It changes the runtime","It creates a new alias automatically"],e:"Published versions cannot be modified. Aliases are mutable pointers to versions."},
{d:2,q:"Which AWS CodePipeline feature pauses a pipeline until a person reviews it before production?",o:["Manual approval action","Source action","Build action","Invoke action"],e:"A manual approval action waits for an approve or reject decision, optionally notifying through SNS."},
{d:2,q:"Which service stores and shares software packages such as npm, Maven, and pip artifacts?",o:["AWS CodeArtifact","Amazon ECR","Amazon EFS","AWS Config"],e:"CodeArtifact is a managed package repository. Amazon ECR stores container images."},
{d:2,q:"Which Elastic Beanstalk deployment policy launches a full set of new instances in a separate Auto Scaling group and offers fast, safe rollback?",o:["Immutable","All at once","Rolling","Rolling with additional batch"],e:"Immutable deployments leave the existing instances untouched until the new ones pass health checks."},
{d:2,q:"Which Elastic Beanstalk deployment policy is the fastest but can cause a brief outage?",o:["All at once","Immutable","Traffic splitting","Rolling with additional batch"],e:"All at once updates every instance simultaneously."},
{d:2,q:"Which Elastic Beanstalk deployment policy keeps full capacity during a deployment by launching an extra batch of instances?",o:["Rolling with additional batch","Rolling","All at once","In-place"],e:"The extra batch keeps capacity at 100 percent while the others are updated."},
{d:2,q:"Where do you place custom resource and configuration settings in an Elastic Beanstalk source bundle?",o:[".ebextensions directory",".github/workflows directory","buildspec.yml","appspec.yml"],e:".ebextensions holds .config files that customize the environment."},
{d:2,q:"Which service deploys feature flags and configuration changes gradually with validation and automatic rollback on alarms?",o:["AWS AppConfig","AWS Config","AWS CloudFormation","Amazon Macie"],e:"AppConfig is a capability of AWS Systems Manager for safe configuration rollout."},
{d:2,q:"After changing the resources or methods of an API Gateway REST API, what must you do for the changes to reach callers?",o:["Deploy the API to a stage","Restart the API","Regenerate the API key","Nothing; changes apply immediately"],e:"REST API changes take effect only after a deployment to a stage."},
{d:2,q:"Which API Gateway feature routes a percentage of traffic to a new deployment of a stage?",o:["Canary release deployment","Usage plans","Request validators","Stage variables"],e:"A canary release sends a configurable share of requests to the new deployment."},
{d:2,q:"A single API Gateway API has dev and prod stages that must call different Lambda aliases. Which feature should be used?",o:["Stage variables","Usage plans","Cognito groups","Request validators"],e:"Stage variables act like environment variables and can be referenced in integration settings such as the Lambda function alias."},
{d:2,q:"Which AWS CDK command produces a CloudFormation template from the app code without deploying it?",o:["cdk synth","cdk bootstrap","cdk destroy","cdk init"],e:"cdk synth synthesizes the template. cdk bootstrap prepares the environment, and cdk deploy deploys."},
{d:2,q:"What is the maximum unzipped size of a Lambda deployment package, including layers, when deployed as a .zip archive?",o:["250 MB","50 MB","10 GB","512 MB"],e:"Zip packages are limited to 250 MB unzipped. Container images can be up to 10 GB."},
{d:2,q:"A Lambda function is packaged as a 2 GB container image. Where is the image stored?",o:["Amazon ECR","Amazon S3","AWS CodeArtifact","Amazon EFS"],e:"Lambda container images must be in an Amazon ECR repository."},
{d:2,q:"Which TWO are deployment types for CodeDeploy on EC2 and on-premises instances?",o:["In-place","Blue/green","Canary","Immutable"],ma:[0,1],e:"Canary and linear apply to Lambda and ECS. Immutable is an Elastic Beanstalk policy."},
{d:2,q:"Which TWO tools define serverless infrastructure as code that is deployed through CloudFormation?",o:["AWS SAM","AWS CDK","aws s3 sync","Amazon Inspector"],ma:[0,1],e:"SAM extends CloudFormation syntax. CDK synthesizes CloudFormation templates from code."},
{d:2,q:"In a CloudFormation template, which intrinsic function returns an attribute of a resource, such as the ARN of an SQS queue?",o:["Fn::GetAtt","Ref","Fn::Join","Fn::Select"],e:"Ref returns the resource's main identifier (for a queue, its URL). GetAtt returns other attributes such as Arn."},
{d:2,q:"A CloudFormation template must use a different AMI ID for each Region. Which section and function are typically used?",o:["Mappings with Fn::FindInMap","Outputs with Fn::ImportValue","Conditions with Fn::And","Metadata with Fn::Sub"],e:"A Mappings section is a lookup table, and FindInMap retrieves a value by key such as the Region."},
{d:2,q:"A CloudFormation resource should be created only in the production environment. Which feature controls this?",o:["Conditions","Mappings","Outputs","Transform"],e:"Conditions use parameter values to decide whether a resource is created."},
{d:2,q:"A CloudFormation stack creation fails partway. What happens by default?",o:["The stack rolls back and the resources created so far are deleted","The stack keeps the created resources and stops","The failed resource is retried forever","The template is deleted"],e:"Rollback on failure is the default. You can disable it to keep resources for troubleshooting."},
{d:2,q:"A template needs to run custom logic during stack creation, such as calling a third-party API. Which feature supports this?",o:["Custom resources backed by Lambda","Change sets","Stack policies","Drift detection"],e:"Custom resources invoke a Lambda function or SNS topic during create, update, and delete."},
{d:2,q:"Which CloudFormation feature deploys the same stack to multiple accounts and Regions with one operation?",o:["StackSets","Nested stacks","Change sets","Stack policies"],e:"StackSets extend stacks across accounts and Regions."},
{d:2,q:"A CloudFormation Auto Scaling group should not be considered created until its instances finish installing software. Which feature handles this?",o:["CreationPolicy with cfn-signal","DeletionPolicy","UpdateReplacePolicy","DependsOn"],e:"CreationPolicy waits for a specified number of success signals sent by cfn-signal before the resource is marked complete."},
{d:2,q:"Which SAM CLI command runs a Lambda function locally in a container using a test event?",o:["sam local invoke","sam deploy","sam package","sam delete"],e:"sam local invoke runs the function in a Docker container that emulates Lambda."},
{d:2,q:"What is the benefit of SAM policy templates such as DynamoDBCrudPolicy?",o:["They grant common least-privilege permissions with a short declaration","They automatically encrypt tables","They create the table","They add API keys"],e:"Policy templates expand into IAM policies scoped to the resources you name."},
{d:2,q:"Which resource type does the SAM transform provide for a simple DynamoDB table with minimal configuration?",o:["AWS::Serverless::SimpleTable","AWS::Serverless::Function","AWS::Serverless::StateMachine","AWS::Serverless::LayerVersion"],e:"SimpleTable creates a DynamoDB table with a single primary key. SAM also provides Function, Api, HttpApi, Application, LayerVersion, and StateMachine types."},
{d:2,q:"In the AWS CDK, what do L2 constructs provide compared with L1 constructs?",o:["Higher-level abstractions with sensible defaults and helper methods","A one-to-one mapping to CloudFormation resources with no defaults","Pre-built complete architectures only","Direct access to the console"],e:"L1 (Cfn) constructs mirror CloudFormation. L2 constructs add defaults and conveniences such as grant methods. L3 constructs are patterns."},
{d:2,q:"How do the stages of an AWS CodePipeline share files such as built artifacts?",o:["Through an artifact store in Amazon S3","Through shared EBS volumes","Through environment variables","Through SQS messages"],e:"CodePipeline stores input and output artifacts in an S3 bucket."},
{d:2,q:"Which CodeDeploy appspec hook is used to run tests that confirm a deployment is working on EC2 or on-premises instances?",o:["ValidateService","BeforeInstall","ApplicationStop","AfterInstall"],e:"The order is ApplicationStop, BeforeInstall, AfterInstall, ApplicationStart, ValidateService."},
{d:2,q:"How can a CodeDeploy deployment roll back automatically if a CloudWatch alarm fires during the rollout?",o:["Configure automatic rollback with alarm monitoring on the deployment group","Delete the application revision","Disable the alarm","Increase the minimum healthy hosts"],e:"Deployment groups can roll back on deployment failure or when specified alarms trigger."},
{d:2,q:"Which Amazon ECS deployment type shifts traffic between two task sets behind a load balancer and is orchestrated by AWS CodeDeploy?",o:["Blue/green","Rolling update","In-place","Canary on EC2 only"],e:"The ECS default is a rolling update that replaces tasks gradually. Blue/green through CodeDeploy shifts traffic between task sets."},
{d:2,q:"Old container images pile up in an Amazon ECR repository and increase costs. What feature expires them automatically?",o:["Lifecycle policies","Image scanning","Replication rules","Repository policies"],e:"ECR lifecycle policies remove images by age or count."},
{d:2,q:"Which Elastic Beanstalk environment tier processes background jobs by reading messages from an SQS queue?",o:["Worker environment","Web server environment","Single-instance environment","Immutable environment"],e:"Worker environments run a daemon that pulls messages from SQS and posts them to the application."},
{d:2,q:"How does a blue/green deployment work in Elastic Beanstalk?",o:["Deploy to a new environment and swap the environment URLs (CNAMEs)","Update instances one at a time in place","Edit the load balancer manually","Delete the old environment first"],e:"Swapping environment URLs redirects traffic, and swapping back rolls back."},
{d:2,q:"In an AWS SAM template, which properties enable gradual traffic shifting for a Lambda function with CodeDeploy?",o:["AutoPublishAlias and DeploymentPreference","Layers and Tracing","Events and Policies","Timeout and MemorySize"],e:"AutoPublishAlias publishes a version and updates the alias, and DeploymentPreference sets canary or linear shifting plus alarms."},
{d:2,q:"Which service provides a Git-connected, fully managed CI/CD and hosting workflow for full-stack web and mobile apps?",o:["AWS Amplify Hosting","AWS CodeArtifact","Amazon Lightsail","AWS Backup"],e:"Amplify Hosting connects a repository branch and builds and deploys on each push."},
{d:2,q:"A developer has an OpenAPI definition for a REST API. What is the quickest way to create the API in API Gateway?",o:["Import the OpenAPI definition","Recreate each method manually in the console","Write a Lambda function that creates it","Use a Route 53 alias"],e:"API Gateway can import OpenAPI (Swagger) files, and SAM supports DefinitionBody."},
{d:2,q:"Which command output authenticates the Docker client to Amazon ECR before pushing an image?",o:["aws ecr get-login-password piped to docker login","aws ecr create-repository","docker push without credentials","aws s3 sync"],e:"The token from get-login-password is passed to docker login for the registry URL."},
{d:2,q:"Application settings differ for dev, test, and prod. How can they be organized in Systems Manager Parameter Store?",o:["Use hierarchical names such as /myapp/prod/db_url","Create one parameter for all environments","Store them in one S3 object","Use CloudFormation outputs only"],e:"Hierarchies let you fetch a whole path with GetParametersByPath and scope IAM access to a prefix."},
{d:2,q:"Which TWO are ways to deploy a Lambda function packaged as a container image?",o:["Push the image to Amazon ECR and create the function from it","Use the SAM CLI to build and deploy it","Upload the image directly in the Lambda console as a zip","Store the image in Amazon S3 and reference its URL","Store the image in AWS CodeArtifact"],ma:[0,1],e:"The function must reference an image in ECR, and SAM can build, push, and deploy it."},

// ---------- Domain 3: Troubleshooting and Optimization ----------
{d:3,q:"Which service lets developers search and analyze Lambda log data using a query language?",o:["Amazon CloudWatch Logs Insights","AWS Config","AWS Trusted Advisor","AWS Artifact"],e:"Logs Insights queries log groups interactively."},
{d:3,q:"Which service helps find the cause of latency across a chain of microservice calls by tracing requests?",o:["AWS X-Ray","AWS CloudTrail","AWS Config","Amazon Inspector"],e:"X-Ray builds a service map and traces for requests."},
{d:3,q:"In AWS X-Ray, which data can be used to filter and search traces?",o:["Annotations","Metadata","Log lines","IAM policies"],e:"Annotations are indexed key-value pairs. Metadata is stored but not searchable."},
{d:3,q:"How do you enable X-Ray tracing for a Lambda function?",o:["Enable active tracing and allow X-Ray writes in the execution role","Run the X-Ray daemon inside the function","Install the CloudWatch agent","Enable CloudTrail data events"],e:"Lambda runs the X-Ray daemon for you. The role needs permission such as xray:PutTraceSegments."},
{d:3,q:"Which API publishes custom application metrics to Amazon CloudWatch?",o:["PutMetricData","PutLogEvents","PutTraceSegments","PutItem"],e:"PutMetricData sends custom metrics. The embedded metric format can also emit metrics from logs."},
{d:3,q:"A Lambda function returns 429 TooManyRequestsException during traffic spikes. What should the developer do?",o:["Request an increase of the account concurrency quota or adjust reserved concurrency","Lower the memory setting","Increase the timeout","Add a layer"],e:"429 means concurrency limits were reached. Reserved concurrency guarantees capacity for a function but also caps it."},
{d:3,q:"Which feature keeps Lambda execution environments initialized to reduce cold-start latency?",o:["Provisioned concurrency","Reserved concurrency","A longer timeout","Layers"],e:"Provisioned concurrency pre-initializes environments. Reserved concurrency does not pre-warm."},
{d:3,q:"An application receives ProvisionedThroughputExceededException from DynamoDB. What should the client do first?",o:["Retry with exponential backoff and jitter","Retry immediately in a tight loop","Switch the table to Scan operations","Disable retries"],e:"Backoff with jitter spreads out retries. Also consider auto scaling, on-demand mode, or fixing hot keys."},
{d:3,q:"Which service provides microsecond read latency for DynamoDB with minimal code changes?",o:["Amazon DynamoDB Accelerator (DAX)","Amazon ElastiCache for Redis","Amazon CloudFront","S3 Transfer Acceleration"],e:"DAX is an in-memory cache that is API-compatible with DynamoDB."},
{d:3,q:"API Gateway returns 502 Bad Gateway for a Lambda proxy integration. What is a likely cause?",o:["The function returned a response that is not in the required format","A missing API key","Throttling from a usage plan","An expired Cognito token"],e:"Throttling returns 429, and auth problems return 401 or 403."},
{d:3,q:"A Lambda function that sometimes runs for 60 seconds processes the same SQS messages more than once. The queue's visibility timeout is 30 seconds. What is the fix?",o:["Increase the queue's visibility timeout to exceed the function timeout","Switch to short polling","Delete the dead-letter queue","Reduce the function memory"],e:"If the timeout expires first, the message becomes visible again and is delivered to another invocation."},
{d:3,q:"A Lambda function invoked asynchronously fails. How many times does Lambda retry by default?",o:["Two additional times","Zero times","Five times","Indefinitely"],e:"The default is two retries and is configurable from 0 to 2. Use destinations or a DLQ to capture failures."},
{d:3,q:"Which Lambda feature can send the result of failed asynchronous invocations to SQS, SNS, another Lambda function, or EventBridge?",o:["Destinations","Provisioned concurrency","Layers","Function URLs"],e:"Destinations support on-success and on-failure routing."},
{d:3,q:"A Kinesis producer gets ProvisionedThroughputExceededException on a few shards. Which fix helps?",o:["Use partition keys that spread records evenly and add shards if needed","Use a single partition key","Increase the retention period","Replace the stream with SNS"],e:"A hot shard means uneven keys. Each shard accepts 1 MB/s or 1,000 records/s."},
{d:3,q:"A DynamoDB Scan with a FilterExpression returns few items but consumes a lot of read capacity. Why?",o:["Filters apply after the read, so all scanned data consumes capacity","Filter expressions double the cost","Scans always use strongly consistent reads","Filters are billed separately"],e:"Use Query with key conditions or an index to read less data."},
{d:3,q:"How can a developer increase Amazon S3 request throughput for highly parallel workloads?",o:["Spread objects across multiple prefixes and issue parallel requests","Put all objects under a single prefix","Disable versioning","Use single-threaded uploads"],e:"Each prefix supports at least 3,500 write and 5,500 read requests per second."},
{d:3,q:"Which caching strategy populates the cache only when data is requested and not found in it?",o:["Lazy loading","Write-through","Eager preloading","Time-to-live only"],e:"Lazy loading can serve stale data, while write-through keeps the cache current at the cost of extra writes."},
{d:3,q:"A team needs to find out which IAM identity deleted a DynamoDB table. Which service provides the answer?",o:["AWS CloudTrail","Amazon CloudWatch metrics","AWS X-Ray","AWS Trusted Advisor"],e:"CloudTrail records API calls, including who made them and when."},
{d:3,q:"Lambda log groups keep logs indefinitely by default. How can the developer limit storage cost?",o:["Set a retention period on the log group","Delete the function","Disable CloudWatch","Reduce the memory setting"],e:"Retention settings expire old log events automatically."},
{d:3,q:"Which approach reduces latency and origin load for static assets served to users worldwide?",o:["Serve them through Amazon CloudFront with caching","Use a larger EC2 instance","Enable Multi-AZ on RDS","Add more SQS queues"],e:"CloudFront caches content at edge locations close to users."},
{d:3,q:"How can an API reduce repeated calls to its backend for identical requests?",o:["Enable API caching on the stage with a TTL","Increase the burst limit","Require an API key","Attach AWS WAF"],e:"API Gateway can cache endpoint responses for a configured time to live."},
{d:3,q:"A CPU-bound Lambda function runs slowly. What should the developer try?",o:["Increase memory and compare duration and cost","Decrease memory","Increase the timeout only","Lower reserved concurrency"],e:"More memory brings more CPU, which can shorten duration enough to cost the same or less."},
{d:3,q:"Which TWO actions reduce the impact of Lambda cold starts?",o:["Use provisioned concurrency","Minimize package size and initialization code","Increase the function timeout","Attach a dead-letter queue"],ma:[0,1],e:"Pre-warmed environments and lighter initialization reduce startup latency."},
{d:3,q:"Which TWO techniques are recommended when AWS API calls are throttled?",o:["Exponential backoff","Adding random jitter to retry delays","Immediate unlimited retries","Ignoring the error"],ma:[0,1],e:"Backoff with jitter prevents synchronized retry storms."},
{d:3,q:"A Lambda function in a VPC private subnet cannot call a public third-party API. What is the fix?",o:["Route outbound traffic through a NAT gateway in a public subnet","Attach an internet gateway to the private subnet only","Add the function to a larger security group","Increase the function timeout"],e:"VPC-attached functions have no public IP, so internet access requires a NAT gateway. VPC endpoints cover AWS services privately."},
{d:3,q:"Which Lambda metric shows how far behind a function is when processing a Kinesis or DynamoDB stream?",o:["IteratorAge","Duration","Throttles","Invocations"],e:"IteratorAge is the age of the last record in the batch when Lambda received it. Rising values mean consumers are falling behind."},
{d:3,q:"How can you alarm on the number of ERROR lines written to a CloudWatch Logs log group?",o:["Create a metric filter, then an alarm on the resulting metric","Enable X-Ray","Use CloudTrail data events","Enable VPC Flow Logs"],e:"Metric filters turn matching log patterns into CloudWatch metrics."},
{d:3,q:"A high-traffic service generates too many X-Ray traces and costs are rising. What reduces the volume?",o:["Configure sampling rules","Turn off CloudWatch Logs","Delete the service map","Remove the X-Ray daemon permissions"],e:"Sampling records a representative subset of requests."},
{d:3,q:"What is the default timeout of a newly created Lambda function?",o:["3 seconds","15 minutes","30 seconds","1 minute"],e:"The default is 3 seconds, and the maximum is 15 minutes."},
{d:3,q:"A Lambda function fails because it runs out of memory. What should the developer do?",o:["Increase the function's memory setting","Increase the timeout","Enable X-Ray","Add a layer"],e:"The REPORT log line shows Max Memory Used. Raising memory also raises CPU."},
{d:3,q:"A table has one very popular partition key, and requests to it are throttled while overall capacity is unused. What approach helps?",o:["Spread writes across more keys, for example by adding a random or calculated suffix (write sharding)","Switch to Scan operations","Increase the item size","Disable auto scaling"],e:"Hot keys limit throughput on a single partition. Sharding the key spreads load across partitions."},
{d:3,q:"An application receives HTTP 503 SlowDown errors from Amazon S3 during heavy request bursts. What should it do?",o:["Retry with exponential backoff and spread requests across prefixes","Switch to a smaller bucket","Disable versioning","Turn on MFA delete"],e:"S3 scales to very high request rates per prefix, so backing off and distributing keys resolves transient throttling."},
{d:3,q:"A CloudFront distribution has a low cache hit ratio even though content rarely changes. What is a likely cause?",o:["The cache key includes many headers, cookies, or query strings that vary per request","The origin is in S3","The distribution uses HTTPS","The TTL is too long"],e:"Forwarding fewer values in the cache key lets more requests share the same cached object."},
{d:3,q:"An API Gateway REST API returns 504 Gateway Timeout for a request that invokes a slow backend. What does this indicate?",o:["The integration did not respond before the integration timeout","The caller sent an invalid API key","The request was blocked by an authorizer","The stage was not deployed"],e:"504 means the backend timed out. A missing or invalid API key returns 403, and throttling returns 429."},
{d:3,q:"A developer wants to know who read a specific object in S3 yesterday. What must have been enabled beforehand?",o:["CloudTrail data events or S3 server access logs","CloudTrail management events only","Lambda logs","X-Ray tracing"],e:"Object-level activity is not recorded by default. CloudTrail data events or S3 server access logging capture it."},
{d:3,q:"An ECS task using the awslogs log driver stops immediately. Where should the developer look first?",o:["The stopped task's reason and its CloudWatch Logs log stream","The Route 53 console","The S3 access logs","The IAM credential report"],e:"The task details show the stop reason and exit code, and the log stream shows the application's output."},
{d:3,q:"A cost report shows S3 charges for storage that is not visible in the bucket's object list. What is a likely cause?",o:["Incomplete multipart uploads","Bucket versioning being disabled","CORS rules","Block Public Access"],e:"Parts of unfinished multipart uploads are stored and billed. A lifecycle rule can abort them after a number of days."},
{d:3,q:"Which TWO help a developer find why a particular API request is slow across several services?",o:["AWS X-Ray traces","CloudWatch Logs Insights queries over a correlated request ID","AWS Artifact reports","Route 53 health checks","AWS Budgets alerts"],ma:[0,1],e:"X-Ray shows per-segment latency, and structured logs with a request ID can be queried across log groups."}
  ]
};
